after.content:
$ErrorActionPreference = 'Stop'
if (-not $IsWindows) { throw 'This smoke must run on native Windows.' }
$root = Split-Path -Parent $PSScriptRoot
Push-Location $root
try {
  & .\gradlew.bat :ji-workspace-local:test --tests '*LocalWorkspaceProviderTest*' --offline --rerun-tasks
  if ($LASTEXITCODE -ne 0) { throw "Windows workspace Tool smoke failed: $LASTEXITCODE" }
  $smokeRoot = Join-Path ([System.IO.Path]::GetTempPath()) "ji-workspace-junction-$PID"
  $outside = Join-Path ([System.IO.Path]::GetTempPath()) "ji-workspace-outside-$PID"
  New-Item -ItemType Directory -Path $smokeRoot,$outside -Force | Out-Null
  try {
    cmd /d /c "mklink /J `"$smokeRoot\escape`" `"$outside`"" | Out-Null
    if (-not (Test-Path "$smokeRoot\escape")) { throw 'Windows junction creation did not succeed.' }
    $env:JI_WORKSPACE_SMOKE_ROOT = $smokeRoot
    & .\gradlew.bat :ji-workspace-local:test --tests '*WindowsWorkspaceSmokeTest*' --offline --rerun-tasks
    if ($LASTEXITCODE -ne 0) { throw "Windows junction escape smoke failed: $LASTEXITCODE" }
  } finally {
    Remove-Item Env:JI_WORKSPACE_SMOKE_ROOT -ErrorAction SilentlyContinue
    if (Test-Path "$smokeRoot\escape") { cmd /d /c "rmdir `"$smokeRoot\escape`"" | Out-Null }
    Remove-Item $smokeRoot,$outside -Recurse -Force -ErrorAction SilentlyContinue
  }
} finally {
  Pop-Location
}
